#include "render_batches.hpp"
#include "captured_scene.hpp"
#include "frontend.hpp"
#include <chrono>
#include <fstream>
#include <iostream>
#include <set>
using namespace ofo;
namespace {
using Clock=std::chrono::steady_clock;
struct Camera {std::string name;Vec eye,target;float fov=70;};
// Expand original leaf bounds to cover every camera rotation too.
Mesh bounds_for(const Mesh&m){Mesh out;out.center=m.center;out.radius=m.radius;if(m.billboard)for(const auto&v:m.vertices)out.radius=std::max(out.radius,length(v.position-v.normal-out.center)+std::hypot(v.normal.x,v.normal.y));return out;}
Json audit(const Geometry&g,const std::vector<Camera>&cameras){auto begin=Clock::now();auto plan=build_render_batches(g);double construction=std::chrono::duration<double,std::milli>(Clock::now()-begin).count();Json rows=Json::array();std::vector<Mesh>bounds;for(auto&m:g.meshes)bounds.push_back(bounds_for(m));
 for(const auto&cam:cameras){auto vp=multiply(perspective(cam.fov*3.14159265f/180,16.f/9,.1f,1800),look_at(cam.eye,cam.target));RenderFrustum f(vp,cam.eye);size_t baseline_draws=0,baseline_triangles=0,draws=0,triangles=0,missing=0,extra=0;std::set<size_t>visible,covered;for(size_t i=0;i<g.meshes.size();i++)if(!g.meshes[i].indices.empty()&&f.visible(bounds[i].center,bounds[i].radius)){visible.insert(i);++baseline_draws;baseline_triangles+=g.meshes[i].indices.size()/3;}for(auto i:plan.unbatched)if(!g.meshes[i].indices.empty()&&f.visible(bounds[i].center,bounds[i].radius)){++draws;triangles+=g.meshes[i].indices.size()/3;covered.insert(i);}for(auto&b:plan.batches)if(f.visible(b.mesh.center,b.mesh.radius)){++draws;triangles+=b.mesh.indices.size()/3;covered.insert(b.members.begin(),b.members.end());}for(auto i:visible)missing+=!covered.count(i);for(auto i:covered)extra+=!visible.count(i);if(missing)throw std::runtime_error("Batch bounds lost a visible original member");
  constexpr int repeats=200;volatile size_t observed=0;auto t0=Clock::now();for(int n=0;n<repeats;n++)for(auto&m:bounds){RenderFrustum rebuilt(vp,cam.eye);observed+=rebuilt.visible(m.center,m.radius);}double baseline_ms=std::chrono::duration<double,std::milli>(Clock::now()-t0).count()/repeats;t0=Clock::now();for(int n=0;n<repeats;n++){RenderFrustum shared(vp,cam.eye);for(auto i:plan.unbatched)observed+=shared.visible(bounds[i].center,bounds[i].radius);for(auto&b:plan.batches)observed+=shared.visible(b.mesh.center,b.mesh.radius);}double batched_ms=std::chrono::duration<double,std::milli>(Clock::now()-t0).count()/repeats;
  rows.push_back({{"camera",cam.name},{"eye",{cam.eye.x,cam.eye.y,cam.eye.z}},{"target",{cam.target.x,cam.target.y,cam.target.z}},{"original_visible_draw_candidates",baseline_draws},{"batched_visible_draw_candidates",draws},{"original_visible_full_detail_triangles",baseline_triangles},{"batched_visible_full_detail_triangles",triangles},{"visible_original_members_lost",missing},{"extra_members_due_to_conservative_batch_bounds",extra},{"host_original_rebuild_frustum_each_mesh_ms",baseline_ms},{"host_shared_frustum_batch_visibility_ms",batched_ms},{"timing_repeats",repeats}});
 }return{{"geometry",geometry_summary(g)},{"plan",plan.report},{"host_construction_ms",construction},{"cameras",rows}};
}
}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("Usage: OpenFORenderBatchAudit ORIGINAL_DATA PACKAGE_DIR [output.json]");Resources r(argv[1]);r.mount(fs::path(argv[2])/"capture_assets","capture_assets");auto menu=load_geometry(r,"tracks/menu/menu1/geometry/track_geom.w32");Frontend frontend(r);std::vector<Camera>menu_cams;for(auto page:{MenuPage::Start,MenuPage::Garage,MenuPage::CarSelect}){frontend.page=page;auto cam=frontend.showroom(3);if(!cam.enabled)throw std::runtime_error("Native menu camera unavailable");menu_cams.push_back({page==MenuPage::Start?"native_title_t3":page==MenuPage::Garage?"native_garage_t3":"native_car_dealer_t3",cam.eye,cam.target,cam.fov});}
 auto forest=load_geometry(r,"tracks/forest/forest1/geometry/track_geom.w32");auto capture=append_captured_scene(forest,r);if(capture.value("instances",0)==0)throw std::runtime_error("Forest captured companion must be mounted");auto spawn=load_spawn(r,"tracks/forest/forest1/a");std::vector<Camera>forest_cams;for(float offset:{0.f,100.f,300.f}){auto p=point(spawn,{0,0,offset});auto forward=unit(direction(spawn,{0,0,1}));forest_cams.push_back({"spawn_forward_offset_"+std::to_string(int(offset)),p-forward*6+Vec{0,3,0},p+forward*12,70});}Json out={{"scope","CPU host construction and visibility only; full menu and Forest1+capture; full detail triangles; no Windows GPU/FPS measurement"},{"windows_gpu_measured",false},{"forest_capture",capture},{"menu",audit(menu,menu_cams)},{"forest",audit(forest,forest_cams)}};if(argc>3){std::ofstream file(argv[3]);if(!file)throw std::runtime_error("Cannot write audit output");file<<out.dump(2)<<'\n';}std::cout<<out.dump(2)<<'\n';
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
